            mm=re.search(r'\buser=(\S+)',msg)
            if mm: login[mm.group(1)]+=1
            else: print('no user',f,i,l)
        if 'db timeout' in msg: db.append((ts,lv,s,msg,f,i))
        if msg.startswith('request done'):
            req+=1
            mm=re.search(r'\blatency_ms=([^\s]+)',msg)
            if not mm: print('no latency',f,i,l); continue
            try: v=float(mm.group(1))
            except: print('bad latency',f,i,l); continue
            if v>2000: over.append((v,ts,s,msg,f,i))
for f in js:
    for i,l in enumerate(open(f),1):
        l=l.rstrip('\n')
        if not l.strip(): continue
        o=json.loads(l); ts=o['ts']; lv=o['level']; s=o['service']; msg=o['msg']
        if lv=='ERROR': errc[s]+=1
        if lv=='WARN' and s=='auth' and msg.startswith('login failed'):
            print('json auth login',f,i,l)
        if 'db timeout' in msg: db.append((ts,lv,s,msg,f,i))
        if msg.startswith('request done'):
            req+=1
            mm=re.search(r'\blatency_ms=([^\s]+)',msg)
            if not mm: print('no latency',f,i,l); continue
            try: v=float(mm.group(1))
            except: print('bad latency',f,i,l); continue
            if v>2000: over.append((v,ts,s,msg,f,i))
print('errc',errc, sum(errc.values()))
print('login',login)
print('db count',len(db))
for x in sorted(db)[:10]: print(x)
print('requests total',req,'over',len(over))
print('over by service',collections.Counter(x[2] for x in over))
