print('exactly2000?',sum(1 for x in over if x[0]==2000))
# inspect latency formats
vals=[]
for f in plain+js:
    for l in open(f):
        if 'request done' in l:
            mm=re.search(r'latency_ms=(\d+)',l)
            if mm: vals.append(int(mm.group(1)))
