import glob, json, re, collections
logs = sorted(glob.glob('logs/*'))
assert len(logs) == 240, len(logs)
error_counts = collections.Counter()
login_warn = collections.Counter()
db_times = []
over_2000 = 0
services = set()

def handle(ts, level, service, msg):
    global over_2000
    services.add(service)
    if level == 'ERROR':
        error_counts[service] += 1
    if level == 'WARN' and service == 'auth' and msg.startswith('login failed'):
        m = re.search(r'\buser=(\S+)', msg)
        if m:
            login_warn[m.group(1)] += 1
    if 'db timeout' in msg:
        db_times.append(ts)
    if msg.startswith('request done'):
        m = re.search(r'\blatency_ms=(\d+)', msg)
        if not m:
            raise SystemExit(f'unparseable request done: {msg!r}')
        if int(m.group(1)) > 2000:
            over_2000 += 1

for path in logs:
    with open(path, encoding='utf-8') as fh:
        for line in fh:
            if not line.strip():
                continue
            if path.endswith('.jsonl'):
                o = json.loads(line)
                handle(o['ts'], o['level'], o['service'], o['msg'])
            else:
                m = re.match(r'^(\S+)\s+(\S+)\s+\[([^\]]*)\]\s+(.*)$', line.rstrip('\n'))
